```go
func (b *SeekerBot) NextShot() (Coord, error) {
	for len(b.targets) > 0 {
		c := b.targets[len(b.targets)-1]
		b.targets = b.targets[:len(b.targets)-1]
		if !b.fired[c] {
			return c, nil
		}
	}
	for b.fired[b.hunt[b.cursor]] {
		b.cursor++
	}
	return b.hunt[b.cursor], nil
}

func (b *SeekerBot) Observe(c Coord, result ShotResult) {
	b.fired[c] = true
	if result == Hit {
		for _, n := range b.ocean.Neighbours(c) {
			if !b.fired[n] {
				b.targets = append(b.targets, n)
			}
		}
	}
}
```

Here `b.fired` is a `map[Coord]bool`, `b.targets` is a slice used as a stack, and `b.hunt` holds the even cells followed by the odd ones.

